package ru.pulsedoma;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import ru.pulsedoma.common.BusinessException;
import ru.pulsedoma.issues.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import static ru.pulsedoma.issues.ExchangeTypes.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("demo") @Transactional
class ExchangeControlFlowTest {
 static final Path DB=temp(),FILES=dir();
 static Path temp(){try{return Files.createTempFile("exchange-control-", ".db");}catch(Exception e){throw new IllegalStateException(e);}}
 static Path dir(){try{return Files.createTempDirectory("exchange-control-files-");}catch(Exception e){throw new IllegalStateException(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->"jdbc:sqlite:"+DB);r.add("storage.demo.path",FILES::toString);}
 static final String H="demo-house-1",R="demo-resident-1",A="demo-admin-1",D="demo-dispatcher-1",X="external-exchange",Y="other-external";
 @Autowired CaseExchangeService flow; @Autowired CaseControlService control; @Autowired ResidentCaseService cases; @Autowired CaseCompletionGuard complete; @Autowired CaseWorkAccess access; @Autowired JdbcTemplate db; @Autowired MockMvc mvc;
 String c;
 @BeforeEach void setup(){db.update("INSERT INTO users(id,display_name,status) VALUES (?,?,'ACTIVE'),(?,?,'ACTIVE')",X,"Получатель",Y,"Другой получатель");c=cases.create(H,CaseKind.PROBLEM,"Учебная протечка — приватное описание",null,UUID.randomUUID().toString(),R).id();}
 int rev(){return cases.get(c,R).revision();}
 int pr(String p){return ((Number)flow.workspace(c,D).packets().stream().filter(v->v.get("id").equals(p)).findFirst().orElseThrow().get("revision")).intValue();}
 String channel(Mode mode){return flow.channel(H,null,new ExchangeRequests.Channel("Организация",Participant.WARRANTY,mode,"Согласованный контакт","Договор и проверка контакта","Только выбранные материалы",ChannelState.VERIFIED,0,"Проверили"),A).getLast().get("id").toString();}
 String proof(String title){var v=cases.upload(c,null,title,("%PDF-1.4 "+title+"\n%%EOF").getBytes(),"application/pdf",0,D);return v.documents().getLast().versions().getFirst().id();}
 ExchangeRequests.Packet request(String channel,List<String> files,int pRevision){return new ExchangeRequests.Packet(channel,"Тема для организации","Текст без личной переписки","Основание передачи","Полномочия проверены","Минимально необходимый состав",false,files,null,"Согласуется с адресатом",pRevision,rev(),"Подготовка материалов");}
 String draft(Mode mode,List<String> files){flow.draft(c,null,request(channel(mode),files,0),D);return flow.workspace(c,D).packets().getFirst().get("id").toString();}
 void move(String p,String step,String proof){flow.decision(p,step,new ExchangeRequests.Decision(pr(p),rev(),"Действие подтверждено",proof),D);}
 String sent(Mode mode){String p=draft(mode,List.of(proof("Для передачи")));move(p,"seal",null);move(p,"send",proof("Подтверждение отправки"));return p;}
 String grant(String p,String target){var token=flow.invite(p,new ExchangeRequests.Invite(pr(p),rev(),"Получатель","Подтверждённый сотрудник организации",2),D);flow.accept(token.token(),target);return token.id();}
 @Test void explicitManifestFreezesVersionsAndDoesNotExposeWholeCase(){String visible=proof("Публичный для получателя"),privateFile=proof("Личная квитанция");String p=draft(Mode.PORTAL,List.of(visible));assertTrue(flow.workspace(c,R).packets().isEmpty());move(p,"seal",null);assertThrows(BusinessException.class,()->flow.draft(c,p,request(channel(Mode.PORTAL),List.of(privateFile),pr(p)),D));move(p,"send",proof("Отправлено"));grant(p,X);var packet=flow.recipient(p,X);assertNull(packet.get("address_snapshot"));assertFalse(packet.containsKey("case_id"));assertFalse(packet.containsKey("author"));assertEquals(1,((List<?>)packet.get("files")).size());assertThrows(BusinessException.class,()->cases.get(c,X));assertThrows(BusinessException.class,()->cases.download(privateFile,X));assertFalse(access.member(H,X));assertFalse(access.staff(H,X));var file=(Map<?,?>)((List<?>)packet.get("files")).getFirst();assertTrue(flow.file(p,file.get("id").toString(),false,X).bytes().length>0);}
 @Test void invitationIsHashedSingleUserBoundAndCannotBeAcceptedBySenderOrResident(){String p=sent(Mode.PORTAL);var i=flow.invite(p,new ExchangeRequests.Invite(pr(p),rev(),"Получатель","Проверка",1),D);assertNotEquals(i.token(),db.queryForObject("SELECT token_hash FROM exchange_invitations WHERE id=?",String.class,i.id()));assertThrows(BusinessException.class,()->flow.accept(i.token(),D));assertThrows(BusinessException.class,()->flow.accept(i.token(),R));flow.accept(i.token(),X);flow.accept(i.token(),X);assertThrows(BusinessException.class,()->flow.accept(i.token(),Y));}
 @Test void revocationExpiryAndServiceChangeInvalidateEveryRecipientRead(){String p=sent(Mode.PORTAL),i=grant(p,X);flow.revoke(i,new ExchangeRequests.Decision(pr(p),rev(),"Сотрудник выбыл",null),D);assertThrows(BusinessException.class,()->flow.recipient(p,X));grant(p,X);db.update("UPDATE exchange_invitations SET expires_at='2020-01-01T00:00:00Z' WHERE accepted_by=?",X);assertThrows(BusinessException.class,()->flow.recipient(p,X));grant(p,X);db.update("UPDATE organization_houses SET status='SUSPENDED' WHERE house_id=?",H);assertTrue(flow.inbox(X).isEmpty());assertThrows(BusinessException.class,()->flow.recipient(p,X));}
 @Test void recipientReplyDraftIsPrivateAndAcceptedFilesRetainProvenance(){String p=sent(Mode.PORTAL);grant(p,X);int before=rev();flow.acknowledge(p,new ExchangeRequests.RecipientAction(pr(p),"Получено"),X);assertTrue(rev()>before);flow.reply(p,new ExchangeRequests.Reply(pr(p),"Ответ организации"),X);assertTrue(( (List<?>)flow.workspace(c,D).packets().getFirst().get("answers")).isEmpty());assertTrue(flow.workspace(c,R).packets().getFirst().get("answers") instanceof List);flow.upload(p,pr(p),"Заключение","%PDF-1.4 answer\n%%EOF".getBytes(),"application/pdf",X);flow.publish(p,new ExchangeRequests.RecipientAction(pr(p),"Проверено и отправлено"),X);assertThrows(BusinessException.class,()->complete.requireComplete(c));flow.review(p,new ExchangeRequests.Review(pr(p),rev(),ReviewDecision.ACCEPT,"Проверили содержание","Получили заключение, готовим следующий шаг"),D);assertEquals("REVIEWED",flow.workspace(c,D).packets().getFirst().get("state"));String version=db.queryForObject("SELECT imported_version_id FROM exchange_reply_files",String.class);assertNotNull(version);assertArrayEquals("%PDF-1.4 answer\n%%EOF".getBytes(),cases.download(version,R).bytes());assertEquals(CaseStatus.IN_PROGRESS,cases.get(c,R).status());complete.requireComplete(c);}
 @Test void clarificationCreatesNewReplyVersionAndDoesNotOverwritePublishedReply(){String p=sent(Mode.PORTAL);grant(p,X);flow.acknowledge(p,new ExchangeRequests.RecipientAction(pr(p),"Получили"),X);flow.reply(p,new ExchangeRequests.Reply(pr(p),"Первый ответ"),X);flow.publish(p,new ExchangeRequests.RecipientAction(pr(p),"Публикация"),X);flow.review(p,new ExchangeRequests.Review(pr(p),rev(),ReviewDecision.CLARIFY,"Нет результатов измерения","Уточняем результаты осмотра"),D);flow.reply(p,new ExchangeRequests.Reply(pr(p),"Второй ответ"),X);assertEquals(2,db.queryForObject("SELECT count(*) FROM exchange_replies WHERE packet_id=?",Integer.class,p));assertEquals("Первый ответ",db.queryForObject("SELECT answer FROM exchange_replies WHERE packet_id=? AND version=1 AND state='RETURNED'",String.class,p));}
 @Test void manualExchangeRequiresRealEvidenceAndDoesNotCloseCase(){String p=draft(Mode.MANUAL,List.of());move(p,"seal",null);assertThrows(BusinessException.class,()->move(p,"send",null));move(p,"send",proof("Отправка"));assertThrows(BusinessException.class,()->move(p,"receive",null));move(p,"receive",proof("Получение"));String responseProof=proof("Ответ");flow.manualAnswer(p,new ExchangeRequests.ManualAnswer(pr(p),rev(),"Мотивированный ответ",responseProof),D);assertThrows(BusinessException.class,()->complete.requireComplete(c));flow.review(p,new ExchangeRequests.Review(pr(p),rev(),ReviewDecision.ACCEPT,"Изучен ответ","Объяснение для жителя"),D);assertNotEquals(CaseStatus.CLOSED,cases.get(c,R).status());}
 @Test void foreignEvidenceAndStaleRevisionsAreRejected(){String p=draft(Mode.MANUAL,List.of()),foreign=cases.create(H,CaseKind.PROBLEM,"Другая проблема",null,UUID.randomUUID().toString(),R).id();var f=cases.upload(foreign,null,"Чужой документ","%PDF-1.4 foreign\n%%EOF".getBytes(),"application/pdf",0,D).documents().getFirst().versions().getFirst().id();move(p,"seal",null);assertThrows(BusinessException.class,()->move(p,"send",f));assertThrows(BusinessException.class,()->flow.decision(p,"send",new ExchangeRequests.Decision(pr(p)-1,rev(),"Старый экран",proof("Отправка")),D));}
 @Test void assignmentGrantsOnlySpecificCaseAndDeputyCanTakeOver(){control.assign(c,new ExchangeRequests.Assignment(D,A,rev(),"План замещения"),A);assertTrue(cases.get(c,A).fullAccess());String other=cases.create(H,CaseKind.PROBLEM,"Иное дело",null,UUID.randomUUID().toString(),R).id();assertThrows(BusinessException.class,()->cases.get(other,A));control.takeover(c,new ExchangeRequests.ControlDecision(rev(),"Подхватил на время отсутствия"),A);assertEquals(A,cases.get(c,R).responsibleUserId());assertEquals(D,control.dashboard(H,A).items().stream().filter(i->i.item().id().equals(c)).findFirst().orElseThrow().deputyId());assertThrows(BusinessException.class,()->control.takeover(c,new ExchangeRequests.ControlDecision(rev(),"Не заместитель"),X));}
 @Test void reassignmentRemovesOnlyAutomaticallyCreatedGrants(){control.assign(c,new ExchangeRequests.Assignment(D,A,rev(),"Замещение"),A);assertTrue(access.coordinator(c,H,A));control.assign(c,new ExchangeRequests.Assignment(D,null,rev(),"Закончилась смена"),D);assertFalse(access.coordinator(c,H,A));cases.assign(c,A,CaseFunction.COORDINATOR,true,rev(),A);control.assign(c,new ExchangeRequests.Assignment(D,A,rev(),"Есть независимое назначение"),A);control.assign(c,new ExchangeRequests.Assignment(D,null,rev(),"Замещение закончено"),D);assertTrue(access.coordinator(c,H,A));}
 @Test void financialAssignmentRequiresExplicitRightsAndManagerSeesNoFinancialText(){c=cases.create(H,CaseKind.PAYMENT,"Приватный финансовый текст",null,UUID.randomUUID().toString(),R).id();assertThrows(BusinessException.class,()->control.assign(c,new ExchangeRequests.Assignment(D,A,rev(),"Попытка"),A));cases.permission(H,D,true,A);cases.permission(H,A,true,A);control.assign(c,new ExchangeRequests.Assignment(D,A,rev(),"Допуски выданы"),A);String p=sent(Mode.PORTAL);grant(p,X);assertThrows(BusinessException.class,()->cases.get(c,X));cases.permission(H,A,false,A);var item=control.dashboard(H,A).items().stream().filter(i->i.item().id().equals(c)).findFirst().orElseThrow();assertFalse(item.item().fullAccess());assertFalse(item.item().description().contains("Приватный"));assertThrows(BusinessException.class,()->control.takeover(c,new ExchangeRequests.ControlDecision(rev(),"Допуск отозван"),A));}
 @Test void escalationTargetsCurrentHouseManagerAndNeedsAcknowledgment(){control.assign(c,new ExchangeRequests.Assignment(D,A,rev(),"Ведение"),A);assertThrows(BusinessException.class,()->control.escalate(c,new ExchangeRequests.Escalate(X,rev(),"Просим решение"),D));control.escalate(c,new ExchangeRequests.Escalate(A,rev(),"Срок ответа нарушен"),D);String e=control.dashboard(H,A).escalations().getFirst().get("id").toString();assertThrows(BusinessException.class,()->control.escalation(e,new ExchangeRequests.Escalation(EscalationState.CLOSED,rev(),"Мимо принятия"),A));control.escalation(e,new ExchangeRequests.Escalation(EscalationState.ACKNOWLEDGED,rev(),"Принято"),A);control.escalation(e,new ExchangeRequests.Escalation(EscalationState.CLOSED,rev(),"План согласован"),A);assertEquals("CLOSED",control.dashboard(H,A).escalations().getFirst().get("state"));}
 @Test void packetDeadlineIsIndependentFromNextStep(){String p=sent(Mode.MANUAL);flow.schedule(p,new ExchangeRequests.Schedule(pr(p),rev(),Instant.parse("2020-01-01T00:00:00Z"),"Согласованный срок","Проверка просрочки"),D);assertNull(cases.get(c,R).dueAt());assertTrue(control.dashboard(H,D).items().getFirst().alerts().contains(Alert.OVERDUE));assertTrue(control.dashboard(H,D).items().getFirst().alerts().contains(Alert.WAITING_RECEIPT));}
 @Test void pilotRequiresAllFourParticipantsAndTwoBillingWorkers(){assertFalse(control.pilot(H,A).ready());for(var p:List.of(Participant.UK,Participant.WARRANTY,Participant.CONTRACTOR,Participant.BILLING))flow.channel(H,null,new ExchangeRequests.Channel("Организация",p,Mode.MANUAL,"Контакт","Проверен","По согласованию",ChannelState.VERIFIED,0,"Подготовка"),A);var r=new ExchangeRequests.Pilot(PilotState.READY_FOR_ACCEPTANCE,"Все участники","План приёмки","Проверка восстановления","Контакты","Обучение","Порядок остановки",0);assertThrows(BusinessException.class,()->control.pilot(H,r,A));cases.permission(H,D,true,A);cases.permission(H,A,true,A);assertTrue(control.pilot(H,r,A).ready());assertEquals(0,db.queryForObject("SELECT count(*) FROM exchange_invitations",Integer.class));}
 @Test void inactiveRecipientAndCancelledPacketsCannotBeUsed(){String p=sent(Mode.PORTAL);grant(p,X);db.update("UPDATE users SET status='DELETED' WHERE id=?",X);assertThrows(BusinessException.class,()->flow.recipient(p,X));db.update("UPDATE users SET status='ACTIVE' WHERE id=?",X);move(p,"cancel",null);assertThrows(BusinessException.class,()->flow.recipient(p,X));assertTrue(flow.inbox(X).isEmpty());}
 @Test void overviewContainsOnlyAccessibleHouseSummaries(){assertEquals(H,control.overview(A).getFirst().id());assertTrue(control.overview(X).isEmpty());assertEquals(1,control.overview(A).getFirst().unassigned());}
 @Test void manifestDownloadEscapesContentAndRequiresSenderAccess(){String p=draft(Mode.MANUAL,List.of(proof("<script>title</script>")));assertThrows(BusinessException.class,()->flow.print(p,D));move(p,"seal",null);String html=flow.print(p,D);assertTrue(html.contains("&lt;script&gt;"));assertFalse(html.contains("<script>title"));assertTrue(html.contains("не подтверждает отправку"));assertThrows(BusinessException.class,()->flow.print(p,R));}
 @Test void httpValidationAndRoleBoundaries()throws Exception{mvc.perform(get("/v1/houses/"+H+"/case-control").header("X-Demo-Session","true")).andExpect(status().isNotFound());mvc.perform(post("/v1/cases/"+c+"/exchange").header("X-Demo-Session","dispatcher").contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(get("/v1/cases/"+c+"/exchange").header("X-Demo-Session","true")).andExpect(status().isOk()).andExpect(jsonPath("$.canWork").value(false));}
}
